from pathlib import Path
import hashlib
import re
import yaml

root = Path('/tmp/dfai-architecture-eval-wz76fgm3/project')
paths = sorted((root / 'docs/specs').rglob('*.md'))
docs = {}
items = {}
for path in paths:
    content = path.read_text()
    assert content.startswith('---\n'), path
    meta = yaml.safe_load(content.split('---', 2)[1])
    assert meta['id'] not in docs, meta['id']
    docs[meta['id']] = (path, meta, content)
    ids = set()
    for block in re.findall(r'```yaml items\n(.*?)\n```', content, re.S):
        for entries in yaml.safe_load(block).values():
            for entry in entries:
                assert entry['id'] not in ids
                ids.add(entry['id'])
    items[meta['id']] = ids
assert len(docs) == 7
print('PASS: YAML front matter and source item blocks; 7 unique document IDs')

new_ids = {'ARC-001', 'ADR-001', 'ADR-002', 'ADR-003', 'VER-001'}
for doc_id in new_ids:
    path, meta, content = docs[doc_id]
    assert meta['status'] in {'draft', 'proposed'}
    assert not meta.get('approved_by')
    for ref in meta.get('upstream', []):
        assert ref['id'] in docs, ref
        target, target_meta, _ = docs[ref['id']]
        assert target_meta['version'] == ref['version']
        if 'item' in ref:
            assert ref['item'] in items[ref['id']], ref
        if ref.get('hash'):
            assert hashlib.sha256(target.read_bytes()).hexdigest() == ref['hash']
    for link in re.findall(r'\]\(([^)]+)\)', content):
        if not link.startswith(('https://', 'http://', '#')):
            assert (path.parent / link.split('#')[0]).resolve().is_file(), (doc_id, link)
print('PASS: new-document upstream references, versions, pinned hashes, local links and draft status')

arc = docs['ARC-001'][2]
requirements = {x for x in items['PRD-001'] if re.fullmatch(r'(?:FR|NFR)-\d{3}', x)}
assert len(requirements) == 6
for req in sorted(requirements):
    rows = [line for line in arc.splitlines() if line.startswith('| ' + req + ' ')]
    assert len(rows) == 1, req
    row = rows[0]
    assert 'BLOCKED:' in row and 'G-01' in row and 'G-02' in row
    assert re.search(r'V-\d{2}', row)
    if req.startswith('FR-'):
        assert all(nfr in row for nfr in ('NFR-001', 'NFR-002', 'NFR-003'))
    if req in {'FR-002', 'FR-003'}:
        assert 'G-03' in row
adr_refs = {ref.get('item') for doc_id in ('ADR-001', 'ADR-002', 'ADR-003')
            for ref in docs[doc_id][1]['upstream'] if ref['id'] == 'PRD-001'}
assert requirements <= adr_refs
assert 'Whole product' in arc
print('PASS: 6 requirement rows, ADR coverage, verification mappings and cross-cutting epic blockers')

expected_sources = {
    'PRD-001': '73a324099d4ea11fd4a99ab8f48f944ce36a2a0e955803de3f918bc9d5ac88ef',
    'POL-001': 'd72a0123479999d2d9e03453f89725b7bccb1bacba5f681c36d0e5a116d66602',
}
report = docs['VER-001'][2]
for doc_id, (path, meta, content) in sorted(docs.items()):
    if doc_id == 'VER-001':
        continue
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    if doc_id in expected_sources:
        assert digest == expected_sources[doc_id], doc_id
    assert digest in report, ('stale verification hash', doc_id)
print('PASS: approved source files unchanged and 6 recorded source/candidate hashes match actual bytes')

